  /**
   * Test {@link EntityBuilder#forIntegrationEvent(String, String)}.
   * <p>
   * Method under test: {@link EntityBuilder#forIntegrationEvent(String, String)}
   */
  @Test
  @MethodsUnderTest({"EntityBuilder EntityBuilder.forIntegrationEvent(String, String)"})
  public void testForIntegrationEvent() throws EntityXMLGeneratorException {
    // Arrange and Act
    EntityBuilder actualForIntegrationEventResult = EntityBuilder.forIntegrationEvent("Integration", "Event");

    // Assert
    assertEquals("<entity type=\"com.symphony.integration.Integration.event.Event\" version=\"1.0\"/>",
        actualForIntegrationEventResult.generateXML());
    Entity buildResult = actualForIntegrationEventResult.build();
    assertEquals("com.symphony.integration.Integration.event.Event", buildResult.getType());
    assertNull(buildResult.getName());
    assertNull(buildResult.getPresentationML());
    assertTrue(buildResult.getAttributes().isEmpty());
    assertTrue(buildResult.getEntities().isEmpty());
  }

